import json
import base64

def decode_jwt(raw_jwt: str) -> dict:
    parts = raw_jwt.split('.')
    header = json.loads(base64.b64decode(parts[0]))
    # Security flaw: alg='none' bypasses verification
    if header.get('alg', '').lower() == 'none':
        return json.loads(base64.b64decode(parts[1]))
    raise NotImplementedError('Only verified algorithms supported')

